sys_ui_action.client_script_v2:
function onClick(g_form) {
	var tableName = g_form.getTableName();

	// 1. Busca os templates cadastrados para a tabela atual via GlideAjax
	var ga = new GlideAjax('x_fub_fundbrad_ev.EVUtils');
	ga.addParam('sysparm_name', 'getTemplatesForTable');
	ga.addParam('sysparm_table', tableName);

	ga.getXMLAnswer(function (answer) {
		var templates = [];
		try {
			templates = JSON.parse(answer || '[]');
		} catch (e) {
			templates = [];
		}

		if (templates.length === 0) {
			g_form.addErrorMessage('Nenhum modelo de resposta ativo foi encontrado para esta tabela.');
			return;
		}

		// 2. Mapeia os templates para o formato de opções suportado pelo g_modal.showFields (Choice / Select)
		// Nota: A API de choices no g_modal espera objetos com 'label' e 'value'
		var choiceOptions = templates.map(function (t) {
			return {
				label: t.name,
				value: t.sys_id
			};
		});

		// Guardamos os corpos dos textos em um mapa global para recuperar depois da escolha
		window._templateBodies = {};
		templates.forEach(function (t) {
			window._templateBodies[t.sys_id] = t.body;
		});

		// 3. Abre o modal com um campo de seleção
		g_modal.showFields({
			title: 'Selecionar Modelo de Resposta',
			instruction: 'Escolha um dos modelos disponíveis abaixo:',
			fields: [{
				type: 'choice', // Campo do tipo seleção/dropdown
				name: 'selected_template',
				label: 'Modelos',
				mandatory: true,
				choices: choiceOptions
			}],
			size: 'md'
		}).then(function (result) {
			if (!result || !result.updatedFields) {
				return;
			}

			var field = result.updatedFields.find(function (item) {
				return item.name === 'selected_template';
			});

			var selectedId = field ? field.value : '';
			if (!selectedId || !window._templateBodies[selectedId]) {
				return;
			}

			var templateText = window._templateBodies[selectedId];

			// 4. Substituição de variáveis dinâmicas do registro atual
			templateText = templateText.replace(/\${number}/g, g_form.getValue('number') || '');
			templateText = templateText.replace(/\${u_nome_solicitante}/g, g_form.getValue('u_nome_solicitante') || '');
			templateText = templateText.replace(/\${u_motivo}/g, g_form.getValue('u_motivo') || '');

			// 5. Insere o texto processado nos Comentários Adicionais
			var comentarioAtual = String(g_form.getValue('comments') || '').trim();
			var novoComentario = comentarioAtual ? comentarioAtual + '\n\n' + templateText : templateText;

			g_form.setValue('comments', novoComentario);
			g_form.addInfoMessage('Modelo de resposta aplicado com sucesso!');
		});
	});
}

sys_ui_action.script:
function resolverAtendimento() {
    var dialog = new GlideModal('x_fub_fundbrad_ev_ev_resolver_modal');

    dialog.setTitle('Resolver Atendimento');
    dialog.setPreference(
        'sysparm_record_id',
        g_form.getUniqueValue()
    );

    dialog.setWidth(600);
    dialog.render();

    return false;
}
